<div style={{ padding: "20px" }}>
<p>计数：{count}</p>
<button onClick={() => setCount(count + 1)}>+1</button>
<input
type="text"
value={inputVal}
onChange={(e) => setInputVal(e.target.value)}
placeholder="请输⼊内容"
style={{ margin: "10px 0" }}
/>
<button onClick={() => setIsShow(!isShow)}>
{isShow ? "隐藏⽂本" : "显⽰⽂本"}
</button>
{isShow && <p>这是通过多个状态控制的⽂本</p>}
</div>
);
